/* Generated by ml/train_export.py from deterministic synthetic labels.
 * Input: signed calibrated X delta in raw MPU6050 counts.
 * This is standalone host-tested logic, not deployed M5 firmware.
 */
#include "tilt_tree.h"

enum tilt_class tilt_tree_predict(long delta_x)
{
    if (delta_x <= -150L) {
        return LEFT_TILT;
    } else {
        if (delta_x <= 149L) {
            return NEUTRAL;
        } else {
            return RIGHT_TILT;
        }
    }
}
